package ingest

import (
	"fmt"
	"os"
	"sort"
	"strings"
	"testing"

	"github.com/advanced-security/codeql-abom/internal/normalize"
	"github.com/advanced-security/codeql-abom/internal/store"
)

// Generated by .github/skills/regenerate-abom-fixtures/scripts/regen-closure-fixture.sh from a
// staged closure tree, and from each repository's own files built as a regular database.
const (
	closureFixtures = "../../testdata/closure/"
	closureFindings = closureFixtures + "findings.sarif"
)

func regularFixture(name, kind string) string {
	return closureFixtures + "regular-" + name + "-" + kind
}

// stagedAttribution is the mapping the fixture tree was staged with, spelled out so this package's
// tests say what ingestion does with an attribution rather than how one is computed.
func stagedAttribution(root string) func(string) (Located, error) {
	staged := map[string]string{
		".github/actions/external/vendor/comp/":  "vendor/comp",
		".github/actions/external/vendor/inner/": "vendor/inner",
		".github/workflows/external/vendor/rw/":  "vendor/rw",
	}
	return func(p string) (Located, error) {
		for prefix, repository := range staged {
			if strings.HasPrefix(p, prefix) {
				return Located{Repository: repository, Path: strings.TrimPrefix(p, prefix)}, nil
			}
		}
		if strings.Contains(p, "/external/") {
			return Located{}, fmt.Errorf("%s was staged by nobody", p)
		}
		return Located{Repository: root, Path: p}, nil
	}
}

type closureCorpus struct {
	s   *store.Store
	in  *Ingester
	ids map[string]int64
}

func newClosureCorpus(t *testing.T) closureCorpus {
	t.Helper()
	s := newTestStore(t)
	c := closureCorpus{s: s, in: New(s, store.NewWriter(s, 0)), ids: map[string]int64{}}
	for _, name := range []string{"octo/app", "octo/other"} {
		id, err := s.UpsertRepository(name, "https://github.com/"+name)
		if err != nil {
			t.Fatal(err)
		}
		c.ids[name] = id
	}
	for _, name := range []string{"vendor/comp", "vendor/inner", "vendor/rw"} {
		id, err := s.InsertUpstreamRepository(name)
		if err != nil {
			t.Fatal(err)
		}
		c.ids[name] = id
	}
	return c
}

func (c closureCorpus) run(t *testing.T, mode, repository, digest string) int64 {
	t.Helper()
	id, err := c.s.RecordQueryRun(store.QueryRun{
		QueryID: "abom-findings.qls", Repository: repository, DBCommit: "c0ffee",
		AnalysisMode: mode, Closure: digest,
	})
	if err != nil {
		t.Fatalf("RecordQueryRun: %v", err)
	}
	return id
}

func (c closureCorpus) ingest(t *testing.T, path string, opts Options) {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	if _, err := c.in.FindingsFromSARIF(f, opts); err != nil {
		t.Fatalf("FindingsFromSARIF(%s): %v", path, err)
	}
}

type storedFinding struct {
	repository, path, rule string
	line                   int
}

func (c closureCorpus) findings(t *testing.T) []storedFinding {
	t.Helper()
	rows, err := c.s.DB().Query(`SELECT r.repository_full_name, COALESCE(f.file_path, ''),
		f.rule_id, f.start_line, f.fingerprint, f.start_column, f.end_line, f.end_column,
		COALESCE(f.result_hash, '')
		FROM abom_finding f JOIN repository r ON r.row_id = f.repository_row_id`)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	out := []storedFinding{}
	for rows.Next() {
		var f storedFinding
		var fingerprint, hash string
		var column, endLine, endColumn int
		if err := rows.Scan(&f.repository, &f.path, &f.rule, &f.line, &fingerprint, &column,
			&endLine, &endColumn, &hash); err != nil {
			t.Fatal(err)
		}
		// Identity by content excludes the repository, so a staged path left in it would make
		// one defect two results.
		want := normalize.ResultHash(f.rule, f.path, fingerprint, normalize.Region{
			StartLine: f.line, StartColumn: column, EndLine: endLine, EndColumn: endColumn})
		if hash != want {
			t.Errorf("%s %s:%d hashes as %s, want the hash of the path its repository reports, %s",
				f.rule, f.path, f.line, hash, want)
		}
		out = append(out, f)
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	sort.Slice(out, func(i, j int) bool {
		return fmt.Sprint(out[i]) < fmt.Sprint(out[j])
	})
	return out
}

// A defect in a staged file belongs to the repository that holds the file, at the path it has
// there; anything else matches no node and is invisible to a policy. Nothing may be stored under
// a staged path, and attribution creates no repository and rewrites none.
func TestAClosureFindingIsStoredAgainstTheRepositoryThatHoldsItsFile(t *testing.T) {
	c := newClosureCorpus(t)
	run := c.run(t, store.AnalysisModeExtended, "octo/app", "digest-app")
	c.ingest(t, closureFindings, Options{
		Repository: "octo/app", QueryRunID: run, CLIVersion: "2.27.1",
		Attribute: stagedAttribution("octo/app"),
	})

	got := c.findings(t)
	want := []storedFinding{
		{"octo/app", ".github/workflows/pr.yml", "abom/actions/actions-lock-missing-for-workflow", 0},
		{"octo/app", ".github/workflows/pr.yml", "actions/missing-workflow-permissions", 12},
		{"octo/app", ".github/workflows/pr.yml", "actions/missing-workflow-permissions", 4},
		{"octo/app", ".github/workflows/pr.yml", "actions/unpinned-tag", 12},
		{"octo/app", ".github/workflows/pr.yml", "actions/unpinned-tag", 7},
		{"vendor/comp", "action.yml", "actions/unpinned-tag", 7},
		{"vendor/inner", "action.yml", "actions/code-injection/critical", 7},
		{"vendor/rw", ".github/workflows/reuse.yml", "actions/code-injection/critical", 10},
		{"vendor/rw", ".github/workflows/reuse.yml", "actions/missing-workflow-permissions", 8},
	}
	sort.Slice(want, func(i, j int) bool { return fmt.Sprint(want[i]) < fmt.Sprint(want[j]) })
	if fmt.Sprint(got) != fmt.Sprint(want) {
		t.Errorf("stored\n%v\nwant\n%v", got, want)
	}
	for _, f := range got {
		if strings.Contains(f.path, "/external/") {
			t.Errorf("%s is stored under a staged path, which no node carries", f.path)
		}
	}

	var repositories, urls int
	if err := c.s.DB().QueryRow(`SELECT COUNT(*), COUNT(repository_url) FROM repository`).
		Scan(&repositories, &urls); err != nil {
		t.Fatal(err)
	}
	if repositories != 5 || urls != 2 {
		t.Errorf("attribution left %d repositories with %d URLs, want the 5 and 2 recorded",
			repositories, urls)
	}
}

// A file ABOM wrote into the database to anchor it is nobody's. A rule firing there reports
// something no one wrote.
func TestAFindingInAFileABOMSynthesizedIsNeverStored(t *testing.T) {
	c := newClosureCorpus(t)
	run := c.run(t, store.AnalysisModeExtended, "octo/app", "digest-app")
	staged := stagedAttribution("octo/app")
	c.ingest(t, closureFindings, Options{
		Repository: "octo/app", QueryRunID: run, CLIVersion: "2.27.1",
		Attribute: func(p string) (Located, error) {
			if p == ".github/workflows/pr.yml" {
				return Located{Excluded: true}, nil
			}
			return staged(p)
		},
	})
	for _, f := range c.findings(t) {
		if f.repository == "octo/app" {
			t.Errorf("%s %s:%d was stored from an excluded file", f.rule, f.path, f.line)
		}
	}
}

// A repository the corpus does not hold is refused rather than created: created here, it would be
// a repository nothing analyzed, counted by every total that counts repositories.
func TestAClosureFindingInARepositoryNobodyRecordedIsRefused(t *testing.T) {
	c := newClosureCorpus(t)
	run := c.run(t, store.AnalysisModeExtended, "octo/app", "digest-app")
	f, err := os.Open(closureFindings)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	_, err = c.in.FindingsFromSARIF(f, Options{
		Repository: "octo/app", QueryRunID: run, CLIVersion: "2.27.1",
		Attribute: func(p string) (Located, error) {
			return Located{Repository: "vendor/unknown", Path: p}, nil
		},
	})
	if err == nil {
		t.Fatal("findings were attributed to a repository the corpus does not hold")
	}
	var n int
	if err := c.s.DB().QueryRow(`SELECT COUNT(*) FROM repository`).Scan(&n); err != nil {
		t.Fatal(err)
	}
	if n != 5 {
		t.Errorf("refusing left %d repositories, want 5", n)
	}
}

// The same defect in the same dependency is one finding however many closures reach it, and one
// finding whether the regular or the extended analysis saw it first. What multiplies is sightings,
// one per evaluation that reported it — never rows.
func TestADependencyInsideManyClosuresIsOneFindingWithASightingPerClosure(t *testing.T) {
	c := newClosureCorpus(t)
	for _, name := range []string{"octo-app", "vendor-comp", "vendor-inner", "vendor-rw"} {
		repository := strings.Replace(name, "-", "/", 1)
		run := c.run(t, store.AnalysisModeRegular, repository, "")
		c.ingest(t, regularFixture(name, "findings.sarif"), Options{
			Repository: repository, QueryRunID: run, CLIVersion: "2.27.1",
		})
	}
	closures := map[string]int64{}
	for _, root := range []string{"octo/app", "octo/other"} {
		closures[root] = c.run(t, store.AnalysisModeExtended, root, "digest-"+root)
		c.ingest(t, closureFindings, Options{
			Repository: root, QueryRunID: closures[root], CLIVersion: "2.27.1",
			Attribute: stagedAttribution(root),
		})
	}

	rows, err := c.s.DB().Query(`SELECT r.repository_full_name, f.rule_id, f.file_path, f.start_line,
		COUNT(*) OVER (PARTITION BY f.repository_row_id, f.rule_id, f.file_path, f.start_line,
		                            f.start_column, f.fingerprint),
		(SELECT GROUP_CONCAT(q.analysis_mode || ':' || q.repository) FROM (
		   SELECT q.analysis_mode, q.repository FROM abom_finding_sighting s
		     JOIN abom_query_run q ON q.row_id = s.query_run_id
		    WHERE s.finding_row_id = f.row_id ORDER BY 1, 2) q)
		FROM abom_finding f JOIN repository r ON r.row_id = f.repository_row_id
		WHERE r.repository_full_name LIKE 'vendor/%'`)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	seen := 0
	for rows.Next() {
		var repository, rule, path, sightings string
		var line, copies int
		if err := rows.Scan(&repository, &rule, &path, &line, &copies, &sightings); err != nil {
			t.Fatal(err)
		}
		seen++
		if copies != 1 {
			t.Errorf("%s %s %s:%d is %d rows, want one defect", repository, rule, path, line, copies)
		}
		// Every finding a closure reported in a dependency is sighted once by each closure.
		if strings.Contains(sightings, "extended") {
			for root := range closures {
				if !strings.Contains(sightings, "extended:"+root) {
					t.Errorf("%s %s:%d is not sighted by %s's closure: %s", rule, path, line,
						root, sightings)
				}
			}
		}
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	if seen == 0 {
		t.Fatal("no dependency finding was stored, so this proved nothing")
	}

	// A defect both shapes report is one row carrying both, which is what keeps it in the
	// regular totals it was already in.
	var shared int
	if err := c.s.DB().QueryRow(`SELECT COUNT(*) FROM abom_finding_regular r
		JOIN abom_finding_extended e ON e.row_id = r.row_id`).Scan(&shared); err != nil {
		t.Fatal(err)
	}
	if shared != 6 {
		t.Errorf("%d findings are in both shapes, want the 6 a regular analysis also reports", shared)
	}
}
